(function(){
'use strict';
const S=window.TOKShared;
let state=S.loadState();
const JOURNEY_VERSION=8;
if(state.answers?.journeyVersion!==JOURNEY_VERSION){
  const oldCode=state.answers?.studentCode||'';
  S.clearState(); state=S.createSession(); state.answers.journeyVersion=JOURNEY_VERSION; if(oldCode) state.answers.studentCode=oldCode; S.saveState(state);
}
let currentKey=state.answers.currentNode||'welcome';
let activeTimer=null;

const {criteria,museums,constructed,caseCatalog,firstPools,transferPool,secondPools}=window.TOKContent;

const rules={
  instinctWhy:{minWords:16,minUnique:9,minRecognizedPct:68},
  challenge1Reflection:{minWords:16,minUnique:9,minRecognizedPct:68},
  challenge2Reflection:{minWords:16,minUnique:9,minRecognizedPct:68},
  sourceReflection:{minWords:18,minUnique:10,minRecognizedPct:68},
  framework:{minWords:22,minUnique:12,minRecognizedPct:68},
  finalReason:{minWords:32,minUnique:17,minRecognizedPct:68},
  metacognition:{minWords:20,minUnique:11,minRecognizedPct:68},
  customCaseReflection:{minWords:18,minUnique:10,minRecognizedPct:68}
};
const MAX_REPEAT_PCT=28;

function ensureTelemetry(){const t=state.telemetry||(state.telemetry={});t.clipboard||={paste:0,copy:0,cut:0,drop:0};t.typing||={events:0,insertedChars:0,deleteEvents:0,pauses:0,bursts:0,maxBurstEvents:0,activeTypingMs:0,lastAt:0,currentBurstEvents:0};t.fieldTyping||={};t.fieldVisits||={};t.stepTimings||={};t.validation||={};}
ensureTelemetry();
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function q(s){return document.querySelector(s)} function qa(s){return Array.from(document.querySelectorAll(s))}
function checked(n){return q(`[name="${n}"]:checked`)?.value??null} function selected(n){return qa(`[name="${n}"]:checked`).map(x=>x.value)} function val(n){return q(`[name="${n}"]`)?.value||''}
function stanceLabel(v){return ({'-3':'Definitely no','-2':'Probably no','-1':'Leaning no','0':'Not sure / depends','1':'Leaning yes','2':'Probably yes','3':'Definitely yes'})[String(v)]||'--'}
function choiceCard(name,value,title,desc,checkedNow=false){return `<label class="choice-card"><input type="radio" name="${name}" value="${esc(value)}" ${checkedNow?'checked':''}><strong>${esc(title)}</strong>${desc?`<span>${esc(desc)}</span>`:''}</label>`}
function checkCard(name,value,title,desc,checkedNow=false){return `<label class="choice-card"><input type="checkbox" name="${name}" value="${esc(value)}" ${checkedNow?'checked':''}><strong>${esc(title)}</strong>${desc?`<span>${esc(desc)}</span>`:''}</label>`}
function errorBox(){return '<div class="error-note" id="step-error"></div>'}
function showError(msg){const e=q('#step-error');if(e){e.textContent=msg;e.classList.add('show');}else alert(msg)} function clearError(){const e=q('#step-error');if(e){e.textContent='';e.classList.remove('show')}}
function previousChip(text){return `<div class="memory-chip"><span>EARLIER YOU SAID</span><strong>${esc(text)}</strong></div>`}
function mediumGlyph(c){const m=c.mediaClass||'file';const marks={film:'▸ ▸',photo:'◉',painting:'▰',sculpture:'◆',print:'▤',file:'+'};return `<div class="medium-placeholder ${esc(m)}" aria-hidden="true"><span>${esc(marks[m]||'+')}</span><b>${esc(c.medium||c.fileType||'case file')}</b></div>`;}
function imgTag(c,cls=''){const primary=c.remoteImage||c.image||'',fallback=c.image||'';if(!primary)return '';return `<img class="${esc(cls)}" src="${esc(primary)}" data-fallback="${esc(fallback)}" alt="${esc(c.imageAlt||c.title)}" loading="lazy" referrerpolicy="no-referrer" onerror="if(this.dataset.fallback&&this.src!==this.dataset.fallback){this.src=this.dataset.fallback}">`;}
function caseVisual(c){if(c.remoteImage||c.image)return `<figure class="dossier-visual">${imgTag(c)}<figcaption><span>${esc(c.medium||'case image')}</span><span>${esc(c.remoteImage?'representative image / local fallback':(c.imageCredit||c.source||''))}</span></figcaption></figure>`;return mediumGlyph(c);}
function caseHTML(c,fileNo='01'){const src=c.source||'Inquiry Lab',risk=c.sourceRisk||'green',studentUrl=c.studentSource||c.url||'',studentLabel=c.studentSourceLabel||'Open original source';const warning=risk==='red'?'MATURE EXTERNAL SOURCE - may contain explicit or disturbing material':risk==='amber'?'SOURCE MAY CONTAIN MATURE OR PROVOCATIVE MATERIAL':'PRIMARY / OFFICIAL SOURCE';return `<article class="museum-file dossier-file"><div class="dossier-topline"><span>CASE FILE ${esc(fileNo)}</span><span>STATUS / OPEN</span></div><div class="dossier-stamp">REVIEW COPY</div><div class="museum-stamp">${esc(c.eyebrow)}</div><h3>${esc(c.title)}</h3>${caseVisual(c)}<div class="dossier-meta"><div><span>MEDIUM</span><strong>${esc(c.medium||c.fileType||'Case record')}</strong></div><div><span>PERIOD / REGION</span><strong>${esc([c.year,c.region].filter(Boolean).join(' / ')||src)}</strong></div></div><div class="case-briefing"><span>CASE BRIEFING</span><p>${esc(c.text)}</p></div>${(c.evidence&&c.evidence.length)?`<div class="dossier-evidence"><span>EVIDENCE IN THE FILE</span><ul>${c.evidence.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<div class="tension-box"><span>WHY THIS FILE MATTERS</span><strong>${esc(c.pressure)}</strong></div><div class="task-box"><span>YOUR MOVE</span><strong>${esc(c.task||'Classify this work using only the evidence in this file.')}</strong></div>${studentUrl?`<div class="source-handoff ${esc(risk)}"><span>${esc(warning)}</span><p>You already have enough information to make a decision. Open this only if you want to inspect the work, performance, recording, text, trailer, or official record behind the dossier.</p><a class="museum-link" href="${esc(studentUrl)}" target="_blank" rel="noopener">${esc(studentLabel)} <span aria-hidden="true">↗</span></a></div>`:''}</article>`;}
function caseFactChoices(c,name){const f=c.facts||{};return choiceCard(name,'purpose','Purpose',f.purpose||'Why it was made')+choiceCard(name,'work','The work itself',f.work||'What is actually in it')+choiceCard(name,'context','Context',f.context||'Where and how it is presented')+choiceCard(name,'ethics','Ethics',f.ethics||'Consent, harm and treatment of people');}

function promptText(name,label,starter,max=520){return `<div class="prompt-block"><label class="field response-field"><span>${esc(label)}</span><div class="starter">${esc(starter)}</div><div class="response-shell" data-response-name="${name}"><textarea name="${name}" maxlength="${max}" placeholder="Write 1-3 short sentences."></textarea><div class="response-water" aria-hidden="true"></div><div class="response-meter" aria-hidden="true"><div class="response-meter-bar"></div><div class="response-marker"></div></div></div></label></div>`}
function responseQuality(name,text){const r=rules[name];if(!r)return {ok:true,issues:[]};const s=S.responseStats(text),issues=[];if(s.words<r.minWords)issues.push('length');if(s.unique<r.minUnique)issues.push('variety');if(s.words&&s.recognizedPct<r.minRecognizedPct)issues.push('clarity');if(s.words>=r.minWords&&s.maxRepeatPct>MAX_REPEAT_PCT)issues.push('repetition');return {ok:!issues.length,issues,stats:s};}
function responsePrompt(x){const k=new Set(x.issues);if(k.has('clarity'))return 'Rewrite this in clear, normal sentences so another student could understand your idea.';if(k.has('repetition'))return 'You are repeating the same idea. Add one new reason, detail, or example.';if(k.has('length'))return 'Good start. Add one more sentence explaining why.';return 'Add one more clear reason or example before moving on.';}
function responseReadiness(name,text){const r=rules[name];if(!r)return 0;const s=S.responseStats(text||'');if(!s.words)return 0;const lengthScore=Math.min(1,s.words/r.minWords);const uniqueScore=Math.min(1,s.unique/r.minUnique);const clarityScore=s.words<4?Math.min(.35,lengthScore):Math.min(1,s.recognizedPct/r.minRecognizedPct);let repetitionScore=1;if(s.words>=r.minWords&&s.maxRepeatPct>MAX_REPEAT_PCT){repetitionScore=Math.max(0,1-((s.maxRepeatPct-MAX_REPEAT_PCT)/(100-MAX_REPEAT_PCT||1)));}const score=(lengthScore*.48)+(uniqueScore*.24)+(clarityScore*.18)+(repetitionScore*.10);return Math.max(0,Math.min(1,score));}
function updateResponseMeter(el){if(!el||el.tagName!=='TEXTAREA')return;const shell=el.closest('.response-shell');if(!shell)return;const score=responseReadiness(el.name||'',el.value||'');const pct=Math.round(score*100);shell.style.setProperty('--response-progress',pct+'%');shell.classList.toggle('is-active',pct>3);shell.classList.toggle('is-ready',pct>=100);}
function initResponseMeters(){qa('.response-shell textarea').forEach(el=>{updateResponseMeter(el);el.addEventListener('input',()=>updateResponseMeter(el));});}
function recordValidation(name,x,passed){const v=state.telemetry.validation[name]||(state.telemetry.validation[name]={attempts:0,length:0,variety:0,clarity:0,repetition:0,resolved:false});if(passed){if(v.attempts)v.resolved=true;}else{v.attempts++;for(const i of x.issues)v[i]=(v[i]||0)+1;v.resolved=false;}S.saveState(state);}
function validateText(name){const x=responseQuality(name,val(name));if(x.ok){recordValidation(name,x,true);return true;}recordValidation(name,x,false);showError(responsePrompt(x));q(`[name="${name}"]`)?.focus();return false;}

function getPrimaryReason(){return state.answers.primaryReason||'meaning';}
function hashKey(str){let h=2166136261>>>0;for(const ch of String(str||'')){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)>>>0;}return h>>>0;}
function chooseCase(slot,key,ids){const a=state.answers;a.caseSelections||={};const saved=a.caseSelections[slot];if(saved&&caseCatalog[saved])return caseCatalog[saved];const used=new Set((a.encountered||[]).map(x=>x.id));let candidates=(ids||[]).filter(id=>caseCatalog[id]&&!used.has(id));if(!candidates.length)candidates=(ids||[]).filter(id=>caseCatalog[id]);const seed=((state.seed>>>0)^hashKey(`${slot}|${key}|${a.studentCode||''}`))>>>0;const picked=S.shuffled(candidates,seed)[0]||'fuses';a.caseSelections[slot]=picked;S.saveState(state);return caseCatalog[picked];}
function firstCase(){const r=getPrimaryReason();return chooseCase('challenge1',r,firstPools[r]||firstPools.meaning);}
function secondCase(){const a=state.answers.challenge1Verdict,p=state.answers.nextPressure||'context';const side=(a==='yes'||a==='both')?'yes':'no';return chooseCase('challenge2',`${p}:${side}`,secondPools[p]?.[side]||secondPools.context.no);}
function transferCase(){return chooseCase('transfer','transfer',transferPool);}
function recordEncounter(c,slot){if(!c?.id)return;const a=state.answers;a.encountered||=[];if(!a.encountered.some(x=>x.id===c.id)){a.encountered.push({id:c.id,title:c.title,medium:c.medium||'',mediaClass:c.mediaClass||'file',image:c.image||'',remoteImage:c.remoteImage||'',imageAlt:c.imageAlt||c.title,source:c.source||'Inquiry Lab',url:c.studentSource||c.url||'',slot,decision:'',evidence:'',hover:c.hover||c.pressure||'',year:c.year||'',region:c.region||'',sourceRisk:c.sourceRisk||'green'});S.saveState(state);}}
function updateEncounter(slot,data){const a=state.answers,e=(a.encountered||[]).find(x=>x.slot===slot);if(e){Object.assign(e,data||{});S.saveState(state);}}
function encounterDecisionText(e){if(!e?.decision)return 'Decision not made yet';return e.decision;}
function renderEvidenceRail(){const stack=q('#evidence-stack');if(!stack)return;const items=state.answers.encountered||[];if(!items.length){stack.innerHTML='<div class="evidence-empty"><span></span><span></span><span></span></div>';return;}stack.innerHTML=items.map((e,i)=>{const tilt=((hashKey(e.id)%7)-3)*.65;const primary=e.remoteImage||e.image||'',fallback=e.remoteImage&&e.image?e.image:'';const visual=primary?`<img src="${esc(primary)}" data-fallback="${esc(fallback)}" alt="" referrerpolicy="no-referrer" onerror="if(this.dataset.fallback&&this.src!==this.dataset.fallback){this.src=this.dataset.fallback}">`:`<div class="evidence-glyph ${esc(e.mediaClass)}">${esc((e.medium||'FILE').slice(0,3).toUpperCase())}</div>`;const tip=`${encounterDecisionText(e)}${e.evidence?' · '+e.evidence:''}`;return `<article class="evidence-card" tabindex="0" title="${esc(e.title)}" aria-label="${esc(e.title)}. ${esc(tip)}" style="--tilt:${tilt}deg"><span class="evidence-pin"></span>${visual}<div class="evidence-card-copy"><strong>${esc(e.title)}</strong></div><div class="evidence-tooltip" role="tooltip"><span>${esc(e.title)}</span><strong>${esc(encounterDecisionText(e))}</strong>${e.evidence?`<p>${esc(e.evidence)}</p>`:''}</div></article>`;}).join('');}
function primaryReasonText(){return criteria[getPrimaryReason()]?.plain||'your first rule';}
function primaryReasonText(){return criteria[getPrimaryReason()]?.plain||'your first rule';}
function selectNextNode(node){const map={welcome:'instinct',instinct:'reason',reason:'challenge1',challenge1:'checkpoint1',checkpoint1:'challenge2',challenge2:'memory',memory:'rule',rule:'transfer',transfer:'customcase',customcase:'spectrum',spectrum:'final',final:'complete'};return map[node]||'complete';}
function commitNode(next){state.answers.currentNode=next;state.answers.history||=[];state.answers.history.push(currentKey);state.stepIndex=state.answers.history.length;state.telemetry.currentStepStarted=S.now();S.saveState(state);currentKey=next;render();}
function commitTiming(){const t=state.telemetry,now=S.now();t.stepTimings[currentKey]=(t.stepTimings[currentKey]||0)+Math.max(0,now-(t.currentStepStarted||now));t.currentStepStarted=now;}

function render(){q('#move-label').textContent=currentKey==='welcome'?'ENTRY':currentKey==='complete'?'COMPLETE':`MOVE ${String((state.answers.history||[]).length+1).padStart(2,'0')}`;const screen=q('#screen');({welcome:renderWelcome,instinct:renderInstinct,reason:renderReason,challenge1:renderChallenge1,checkpoint1:renderCheckpoint1,challenge2:renderChallenge2,memory:renderMemory,rule:renderRule,transfer:renderTransfer,customcase:renderCustomCase,spectrum:renderSpectrum,final:renderFinal,complete:renderComplete}[currentKey]||renderWelcome)(screen);q('#next-btn').style.display=currentKey==='complete'?'none':'inline-block';renderEvidenceRail();attachInstrumentation();initResponseMeters();const appRoot=q('#app');if(appRoot&&!appRoot.hidden){appRoot.scrollIntoView({block:'start',behavior:'auto'});}}

function renderWelcome(screen){screen.innerHTML=`<div class="screen-card welcome-card"><div class="eyebrow">NO PREP. NO PERFECT ANSWER.</div><h1>Where does <span class="serif">art</span> stop?</h1><p class="lede">You will make a few choices, meet examples that push back, and see whether your rule survives. You only see one move at a time.</p><div class="split-note"><div><h3>Move quickly at first</h3><p>Your first reaction matters. Do not research before you begin.</p></div><div><h3>Then slow down</h3><p>Some screens will ask for a short explanation before you can continue.</p></div></div><div class="consent-panel subtle-consent"><div class="consent-mark">LOCAL</div><div><strong>Your route is saved on this device</strong><p>Your answers and a basic activity record are included with the teacher handoff.</p><details class="privacy-details"><summary>Privacy details</summary><p>Basic process information is recorded locally for teacher review. Full written answers stay in the PDF, not in the QR code.</p></details></div></div><div class="field-grid compact-grid"><label class="field"><span>Student / group code</span><input id="student-code" maxlength="32" placeholder="e.g. 2B-17" autocomplete="off" value="${esc(state.answers.studentCode||'')}"></label><label class="field"><span>Mode</span><select id="work-mode"><option>Individual</option><option>Pair</option><option>Group</option></select></label></div>${errorBox()}</div>`;q('#work-mode').value=state.answers.workMode||'Individual';}
function scaleHTML(name){return `<div class="scale">${[[-3,'Definitely no'],[-2,'Probably no'],[-1,'Lean no'],[0,'Depends'],[1,'Lean yes'],[2,'Probably yes'],[3,'Definitely yes']].map(([v,l])=>`<label><input type="radio" name="${name}" value="${v}">${l}</label>`).join('')}</div><div class="scale-anchors"><span>cannot be art</span><span>can be art</span></div>`}
function renderInstinct(screen){screen.innerHTML=`<div class="screen-card"><div class="eyebrow">FIRST REACTION</div><h2>Do not overthink it.</h2><p class="lede">Right now, how far do you agree with this claim?</p><div class="prompt-block"><span class="question-label">Pornography can be art.</span>${scaleHTML('initialStance')}</div><div class="prompt-block"><label class="field"><span>How sure are you? <strong id="confidence-value">50</strong>%</span><input id="confidence" type="range" min="0" max="100" step="10" value="50"></label></div>${promptText('instinctWhy','One reason for your answer','Start: I chose this because...')} ${errorBox()}</div>`;q('#confidence').addEventListener('input',e=>q('#confidence-value').textContent=e.target.value);}
function renderReason(screen){const initial=stanceLabel(state.answers.initialStance);screen.innerHTML=`<div class="screen-card"><div class="eyebrow">WHAT SHAPED YOUR ANSWER?</div>${previousChip(initial)}<h2>What mattered most when you chose that answer?</h2><p class="lede">Choose the ONE factor that influenced your first answer most. You can change your thinking later.</p><div class="choice-grid">${Object.entries(criteria).map(([k,c])=>choiceCard('primaryReason',k,c.label,c.plain)).join('')}</div>${errorBox()}</div>`;}
function challengeCommon(screen,num,c){recordEncounter(c,`challenge${num}`);const prior=num===1?`You said this mattered most: ${primaryReasonText()}`:`After the first case you answered: ${state.answers.challenge1VerdictLabel||state.answers.challenge1Verdict}`;const verdictName=`challenge${num}Verdict`,factName=`challenge${num}Fact`;const verdicts=c.forceBinary?choiceCard(verdictName,'yes','Art','For this decision, art is the better primary category.')+choiceCard(verdictName,'no','Not art','For this decision, art is not the better primary category.'):choiceCard(verdictName,'yes','Art','Art is the best single category for this case.')+choiceCard(verdictName,'both','Both','It can fit art and pornography at the same time.')+choiceCard(verdictName,'no','Not art','The evidence keeps it outside art for me.')+choiceCard(verdictName,'unsure','Need one more fact','I cannot settle this case yet.');screen.innerHTML=`<div class="screen-card"><div class="eyebrow">CHALLENGE ${num}</div>${previousChip(prior)}<h2>Open the case file.</h2><p class="lede compact-lede">Read the evidence. Classify this one work. The bigger question can wait.</p>${caseHTML(c,String(num).padStart(2,'0'))}<div class="decision-bridge"><span>DECISION 01</span><strong>How would you classify <em>${esc(c.title)}</em>?</strong></div><div class="prompt-block connected-block"><div class="choice-grid compact-choices">${verdicts}</div></div><div class="decision-bridge secondary"><span>DECISION 02</span><strong>Which piece of evidence mattered most?</strong></div><div class="prompt-block connected-block"><div class="choice-grid compact-choices case-facts">${caseFactChoices(c,factName)}</div></div>${promptText(`challenge${num}Reflection`,'Connect that evidence to your decision','Start: That mattered because...')} ${errorBox()}</div>`;}
function renderChallenge1(screen){challengeCommon(screen,1,firstCase())}
function renderCheckpoint1(screen){const a=state.answers;screen.innerHTML=`<div class="screen-card"><div class="eyebrow">CHECKPOINT</div>${previousChip(`You began: ${stanceLabel(a.initialStance)}. The factor you said mattered most was ${criteria[a.primaryReason]?.label}.`)}<h2>Did this case change how well your first rule works?</h2><div class="choice-grid compact-choices">${choiceCard('checkpointChange','same','Not really','My first rule still works for me.')}${choiceCard('checkpointChange','less','A little','I am less certain than I was.')}${choiceCard('checkpointChange','shift','Yes','I need to change or add to my rule.')}${choiceCard('checkpointChange','more','It strengthened it','The example made my first view clearer.')}</div><div class="prompt-block"><span class="question-label">Which part of your thinking should the next case test?</span><div class="choice-grid compact-choices">${choiceCard('nextPressure','purpose','Purpose','Can something be art if arousal or profit is the main purpose?')}${choiceCard('nextPressure','context','Context','Can a museum or audience change the category?')}${choiceCard('nextPressure','craft','Craft','Can artistic technique make a pornographic work art?')}${choiceCard('nextPressure','ethics','Ethics','Does harm or consent affect whether it counts as art?')}</div></div>${errorBox()}</div>`;}
function renderChallenge2(screen){challengeCommon(screen,2,secondCase())}
function renderMemory(screen){const a=state.answers;const start=stanceLabel(a.initialStance);screen.innerHTML=`<div class="screen-card"><div class="eyebrow">MEMORY CHECK</div><h2>Your first answer is back.</h2>${previousChip(`${start}: “${a.instinctWhy}”`)}<p class="lede">You have now seen two cases. Do not rewrite the old answer. Decide what you would keep and what you would change.</p><div class="prompt-block"><span class="question-label">Which part of your first thinking still feels strongest?</span><div class="choice-grid compact-choices">${choiceCard('keepPart','purpose','Purpose still matters')}${choiceCard('keepPart','work','What is actually in the work still matters')}${choiceCard('keepPart','context','Context matters more than I first thought')}${choiceCard('keepPart','mixed','I need more than one rule')}</div></div>${promptText('sourceReflection','One thing you would change or add now','Start: I would change/add... because...')} ${errorBox()}</div>`;}
function renderRule(screen){const a=state.answers;screen.innerHTML=`<div class="screen-card"><div class="eyebrow">BUILD YOUR RULE</div>${previousChip(`You now think ${a.keepPart==='work'?'what is actually in the work matters':criteria[a.keepPart]?.plain||'more than one factor matters'}.`)}<h2>Build your own decision rule.</h2><p class="lede">Choose TWO or THREE things you think should matter when deciding whether explicit material can count as art.</p><div class="choice-grid">${checkCard('ruleParts','purpose','Purpose matters','What the maker intends')}${checkCard('ruleParts','craft','Craft matters','Technique and artistic choices')}${checkCard('ruleParts','meaning','Meaning matters','Ideas beyond immediate arousal')}${checkCard('ruleParts','context','Context matters','How and where it is presented')}${checkCard('ruleParts','audience','Audience matters','How people actually use or interpret it')}${checkCard('ruleParts','ethics','Ethics matters','Consent, harm and treatment')}</div>${promptText('framework','Put your rule into one or two sentences','Start: Pornography can count as art when... / It should not count as art when...')} ${errorBox()}</div>`;}
function renderTransfer(screen){const a=state.answers,c=transferCase();recordEncounter(c,'transfer');screen.innerHTML=`<div class="screen-card"><div class="eyebrow">DOES YOUR RULE TRAVEL?</div>${previousChip(`Your rule used: ${(a.ruleParts||[]).map(x=>criteria[x]?.label||x).join(', ')}`)}<h2>Try your rule somewhere else.</h2>${caseHTML(c,'T-01')}<div class="decision-bridge"><span>TRANSFER DECISION</span><strong>Using your rule, how would you classify this object?</strong></div><div class="prompt-block connected-block"><div class="choice-grid compact-choices">${choiceCard('transferVerdict','art','Art','Art is the best single category.')}${choiceCard('transferVerdict','both','Both','It can be art and still keep its original function.')}${choiceCard('transferVerdict','not','Not art','Its original function keeps it outside art for me.')}${choiceCard('transferVerdict','unsure','Need one more fact','My rule does not settle it yet.')}</div></div><div class="prompt-block"><span class="question-label">What happened to your rule?</span><div class="choice-grid compact-choices">${choiceCard('transferLesson','works','It held up')}${choiceCard('transferLesson','purpose','Purpose alone is not enough')}${choiceCard('transferLesson','context','Context matters more than I thought')}${choiceCard('transferLesson','complex','I need more than one condition')}</div></div>${errorBox()}</div>`;}

function customMediaClass(m){const s=String(m||'').toLowerCase();if(/film|video|tv/.test(s))return 'film';if(/photo|image|visual/.test(s))return 'photo';if(/paint|draw|illustr/.test(s))return 'painting';if(/sculpt|object|installation/.test(s))return 'sculpture';if(/book|literature|poem|novel|text/.test(s))return 'print';if(/music|song|audio|sound/.test(s))return 'file';return 'file';}
function dataUrlBytes(data){const s=String(data||'');const i=s.indexOf(',');if(i<0)return s.length;return Math.ceil((s.length-i-1)*3/4);}
function makeCustomCardImage(title,medium){const c=document.createElement('canvas');c.width=720;c.height=480;const x=c.getContext('2d');const seed=hashKey(`${title}|${medium}`),hue=seed%360;x.fillStyle='#e9e0ce';x.fillRect(0,0,c.width,c.height);x.fillStyle=`hsl(${hue} 72% 58%)`;x.fillRect(0,0,34,c.height);x.fillStyle='#191919';x.fillRect(48,38,624,6);x.strokeStyle='rgba(25,25,25,.28)';x.setLineDash([12,9]);x.strokeRect(60,60,596,352);x.setLineDash([]);x.save();x.translate(604,365);x.rotate(-.13);x.fillStyle='#dfff4f';x.fillRect(-95,-30,190,60);x.strokeStyle='#191919';x.lineWidth=4;x.strokeRect(-95,-30,190,60);x.fillStyle='#191919';x.font='900 24px Courier New';x.textAlign='center';x.fillText('STUDENT FILE',0,8);x.restore();x.fillStyle='#5c574d';x.font='700 18px Courier New';x.fillText(String(medium||'OTHER').toUpperCase().slice(0,36),78,98);x.fillStyle='#191919';x.font='900 38px Arial';const words=String(title||'STUDENT EVIDENCE').split(/\s+/);let line='',yy=164;for(const word of words){const test=(line+' '+word).trim();if(x.measureText(test).width>500&&line){x.fillText(line,78,yy);line=word;yy+=48;}else line=test;}if(line)x.fillText(line,78,yy);x.fillStyle='rgba(25,25,25,.08)';x.font='900 160px Arial';x.textAlign='right';x.fillText(String(title||'?').trim().charAt(0).toUpperCase()||'?',642,332);x.textAlign='left';x.fillStyle='#191919';x.font='700 15px Courier New';x.fillText('BOUNDARY / ART  ·  CONTRIBUTED EVIDENCE',78,408);let out=c.toDataURL('image/webp',.76);if(!out.startsWith('data:image/webp'))out=c.toDataURL('image/jpeg',.78);return out;}

function compressLocalImage(file){return new Promise((resolve,reject)=>{if(!file||!String(file.type||'').startsWith('image/')){reject(new Error('Choose an image file.'));return;}if(file.size>8*1024*1024){reject(new Error('Choose an image under 8 MB.'));return;}const reader=new FileReader();reader.onerror=()=>reject(new Error('That image could not be read.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('That image format could not be opened.'));img.onload=()=>{const max=720,scale=Math.min(1,max/Math.max(img.naturalWidth||1,img.naturalHeight||1)),w=Math.max(1,Math.round((img.naturalWidth||1)*scale)),h=Math.max(1,Math.round((img.naturalHeight||1)*scale));const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d',{alpha:false});ctx.fillStyle='#f5f0e7';ctx.fillRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);let out=canvas.toDataURL('image/webp',.72);if(!out.startsWith('data:image/webp'))out=canvas.toDataURL('image/jpeg',.74);if(dataUrlBytes(out)>420000){out=canvas.toDataURL(out.startsWith('data:image/webp')?'image/webp':'image/jpeg',.55);}if(dataUrlBytes(out)>520000){reject(new Error('That image is still too large after compression. Choose a smaller image.'));return;}resolve(out);};img.src=reader.result;};reader.readAsDataURL(file);});}
function renderCustomCase(screen){const a=state.answers,c=a.customCase||{},mode=a.customCaseMode||'';screen.innerHTML=`<div class="screen-card custom-case-screen"><div class="eyebrow">YOUR EVIDENCE / OPTIONAL FILE</div><h2>Add one case the archive missed.</h2><p class="lede compact-lede">If you know a work that makes this boundary harder, put it into the case file. It will travel with your evidence and appear in your final dossier.</p><div class="choice-grid compact-choices custom-case-mode">${choiceCard('customCaseMode','add','Add my own file','A book, song, film, performance, advert, image, game, object or other work.')}${choiceCard('customCaseMode','skip','Keep the archive as it is','I do not have a useful example to add right now.')}</div><div id="custom-case-form" class="custom-case-form ${mode==='add'?'show':''}"><div class="custom-file-banner"><span>STUDENT FILE</span><strong>Bring evidence, not shock value.</strong><p>If the underlying work is explicit, use a safe cover, poster, title card or other classroom-safe image. Link to a classroom-appropriate museum page, trailer, review or discussion rather than explicit media.</p></div><div class="field-grid"><label class="field"><span>Work / example</span><input type="text" name="customCaseTitle" maxlength="100" value="${esc(c.title||'')}" placeholder="Title or short name"></label><label class="field"><span>Medium</span><select name="customCaseMedium"><option value="">Choose...</option>${['Literature / text','Music / audio','Film / video','Performance','Advertising','Photography','Visual art','Game / digital','Other'].map(m=>`<option ${c.medium===m?'selected':''}>${m}</option>`).join('')}</select></label></div><div class="field-grid"><label class="field"><span>Creator / source <em>optional</em></span><input type="text" name="customCaseCreator" maxlength="100" value="${esc(c.creator||'')}" placeholder="Artist, author, performer, campaign..."></label><label class="field"><span>Source / discussion link <em>optional — paste allowed here</em></span><input type="url" name="customCaseUrl" maxlength="500" value="${esc(c.url||'')}" placeholder="https://..."></label></div><div class="custom-upload"><div class="custom-upload-copy"><span>OPTIONAL LOCAL IMAGE</span><strong>Cover / poster / safe screenshot / object / abstract image</strong><small>Compressed and saved only on this device.</small></div><label class="button ghost custom-upload-button">Choose image<input id="custom-case-image" type="file" accept="image/*"></label><div id="custom-case-preview" class="custom-case-preview">${c.image?`<img src="${esc(c.image)}" alt="Custom dossier preview">`:'<span>NO IMAGE</span>'}</div></div><label class="custom-safety-check"><input type="checkbox" id="custom-image-safe" ${c.imageSafe?'checked':''}><span>The uploaded image itself is classroom-safe and does not show explicit nudity or sexual activity.</span></label><div class="decision-bridge secondary"><span>YOUR CLASSIFICATION</span><strong>Where does this example sit for you right now?</strong></div><div class="choice-grid compact-choices">${choiceCard('customCaseVerdict','yes','Art','I think this belongs on the art side.')}${choiceCard('customCaseVerdict','both','Both','It complicates the line between art and pornography.')}${choiceCard('customCaseVerdict','no','Not art','I think this belongs outside art.')}${choiceCard('customCaseVerdict','unsure','Challenge case','I am adding it because it makes my rule harder to apply.')}</div>${promptText('customCaseReflection','Why does this example belong in the case?','Start: This example matters because...')}<div id="custom-image-status" class="microcopy"></div></div>${errorBox()}</div>`;const modeEls=qa('[name="customCaseMode"]');modeEls.forEach(el=>{if(el.value===mode)el.checked=true;el.addEventListener('change',()=>{q('#custom-case-form')?.classList.toggle('show',el.value==='add'&&el.checked);});});if(c.verdict){const v=q(`[name="customCaseVerdict"][value="${c.verdict}"]`);if(v)v.checked=true;}const input=q('#custom-case-image');if(input)input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;const status=q('#custom-image-status');status.textContent='Preparing image...';try{const data=await compressLocalImage(file);a.customCaseDraftImage=data;a.customCaseDraftImageName=String(file.name||'').slice(0,120);S.saveState(state);q('#custom-case-preview').innerHTML=`<img src="${esc(data)}" alt="Custom dossier preview">`;status.textContent='Image ready.';}catch(err){status.textContent=err.message||'Could not prepare that image.';input.value='';}});}
function commitCustomCase(){const a=state.answers,mode=checked('customCaseMode');if(!mode){showError('Choose whether to add a file or continue without one.');return false;}a.customCaseMode=mode;if(mode==='skip'){a.customCase=null;a.customCaseDraftImage='';if(!state.route.includes('u:0'))state.route.push('u:0');return true;}const title=val('customCaseTitle').trim(),medium=val('customCaseMedium').trim(),creator=val('customCaseCreator').trim(),url=val('customCaseUrl').trim(),verdict=checked('customCaseVerdict'),reflection=val('customCaseReflection').trim(),uploadedImage=a.customCaseDraftImage||'',image=uploadedImage||a.customCase?.image||makeCustomCardImage(title,medium),safe=q('#custom-image-safe')?.checked||false;if(title.length<3){showError('Give your example a clear title or short name.');return false;}if(!medium){showError('Choose the medium.');return false;}if(!verdict){showError('Classify your example before continuing.');return false;}if(!validateText('customCaseReflection'))return false;if(uploadedImage&&!safe){showError('Confirm that the uploaded image itself is classroom-safe, or remove the image.');return false;}if(url){try{const u=new URL(url);if(!/^https?:$/.test(u.protocol))throw 0;}catch(e){showError('Use a normal http or https source link, or leave the link blank.');return false;}}const id=`student-${state.sessionId}`,c={id,title,medium,creator,url,studentSource:url,source:'Student-added evidence',mediaClass:customMediaClass(medium),image:image||'',imageAlt:`Student-added dossier image for ${title}`,sourceRisk:'student',hover:reflection,text:reflection,pressure:'Student-selected example that challenges or supports their emerging rule.',year:'',region:'Student submission'};a.customCase={title,medium,creator,url,verdict,reflection,image,imageSafe:uploadedImage?safe:true,id};const items=a.encountered||(a.encountered=[]);const existing=items.find(x=>x.id===id);const entry={id,title,medium,mediaClass:c.mediaClass,image:c.image,imageAlt:c.imageAlt,source:c.source,url,slot:'student',decision:`Student classification: ${labelVerdict(verdict)}`,evidence:reflection,hover:reflection,year:'',region:'Student submission',sourceRisk:'student'};if(existing)Object.assign(existing,entry);else items.push(entry);a.customCaseDraftImage='';if(!state.route.includes('u:1'))state.route.push('u:1');return true;}

function spectrumEvidenceCard(e,placed=false){const primary=e.remoteImage||e.image||'';const fallback=e.remoteImage&&e.image?e.image:'';const visual=primary?`<img src="${esc(primary)}" data-fallback="${esc(fallback)}" alt="${esc(e.title)}" referrerpolicy="no-referrer" onerror="if(this.dataset.fallback&&this.src!==this.dataset.fallback){this.src=this.dataset.fallback}">`:`<div class="spectrum-glyph ${esc(e.mediaClass)}">${esc((e.medium||'FILE').slice(0,3).toUpperCase())}</div>`;return `<article class="spectrum-card ${placed?'placed':''}" draggable="true" data-evidence-id="${esc(e.id)}" tabindex="0" title="${esc(e.title)}">${visual}<div><strong>${esc(e.title)}</strong></div></article>`;}
function getSpectrumPlacements(){state.answers.spectrumPlacements||={};return state.answers.spectrumPlacements;}
function setSpectrumPlacement(id,bucket,position){const placements=getSpectrumPlacements();placements[id]={bucket,position:bucket==='spectrum'?Math.max(0,Math.min(100,Math.round(position))):null};S.saveState(state);renderSpectrum(q('#screen'));}
function clearSpectrumPlacement(id){const placements=getSpectrumPlacements();delete placements[id];S.saveState(state);renderSpectrum(q('#screen'));}
function renderSpectrum(screen){const a=state.answers,items=a.encountered||[],placements=getSpectrumPlacements();const unplaced=items.filter(e=>!placements[e.id]);const onLine=items.filter(e=>placements[e.id]?.bucket==='spectrum');const irrelevant=items.filter(e=>placements[e.id]?.bucket==='irrelevant');screen.innerHTML=`<div class="screen-card spectrum-screen"><div class="eyebrow">ASSEMBLE THE CASE</div><h2>What does each file do to <span class="serif">your argument?</span></h2><p class="lede compact-lede">Drag every dossier onto the line. Put a file in the discard tray if it does not actually help answer the pornography-and-art question.</p><div class="spectrum-tray" id="spectrum-tray"><div class="spectrum-tray-label">UNSORTED EVIDENCE</div>${unplaced.length?unplaced.map(e=>spectrumEvidenceCard(e)).join(''):'<div class="tray-empty">All files placed.</div>'}</div><div class="argument-spectrum" id="argument-spectrum"><div class="spectrum-axis"></div><div class="spectrum-zone art-zone"><span>PORNOGRAPHY<br><strong>CAN BE ART</strong></span></div><div class="spectrum-zone grey-zone"><span>GREY AREA</span></div><div class="spectrum-zone not-zone"><span>PORNOGRAPHY<br><strong>IS NOT ART</strong></span></div><div class="spectrum-markers">${onLine.map((e,i)=>{const p=placements[e.id];return `<div class="spectrum-marker" style="--x:${p.position}%;--row:${i%3}" data-evidence-id="${esc(e.id)}">${spectrumEvidenceCard(e,true)}<button type="button" class="spectrum-remove" data-clear-spectrum="${esc(e.id)}" aria-label="Move ${esc(e.title)} back to unsorted">×</button></div>`;}).join('')}</div></div><div class="spectrum-discard" id="spectrum-discard"><div><span>DOESN'T HELP THIS ARGUMENT</span><small>Evidence you think is interesting but irrelevant here.</small></div><div class="discard-stack">${irrelevant.map(e=>`<div class="discard-item" data-evidence-id="${esc(e.id)}">${spectrumEvidenceCard(e,true)}<button type="button" class="spectrum-remove" data-clear-spectrum="${esc(e.id)}" aria-label="Move ${esc(e.title)} back to unsorted">×</button></div>`).join('')}</div></div><div class="spectrum-mobile-controls" id="spectrum-mobile-controls"><span>Select a card, then place it:</span><button type="button" data-mobile-place="15">Supports art</button><button type="button" data-mobile-place="50">Mixed</button><button type="button" data-mobile-place="85">Supports not art</button><button type="button" data-mobile-discard>Irrelevant</button></div>${errorBox()}</div>`;initSpectrumInteractions();}
function initSpectrumInteractions(){let selected=null;const cards=qa('.spectrum-card');cards.forEach(card=>{card.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',card.dataset.evidenceId);e.dataTransfer.effectAllowed='move';});card.addEventListener('click',()=>{selected=card.dataset.evidenceId;qa('.spectrum-card').forEach(c=>c.classList.toggle('selected',c.dataset.evidenceId===selected));});});const spectrum=q('#argument-spectrum');if(spectrum){spectrum.addEventListener('dragover',e=>e.preventDefault());spectrum.addEventListener('drop',e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');const r=spectrum.getBoundingClientRect();setSpectrumPlacement(id,'spectrum',((e.clientX-r.left)/r.width)*100);});spectrum.addEventListener('click',e=>{if(!selected||e.target.closest('.spectrum-card,.spectrum-remove'))return;const r=spectrum.getBoundingClientRect();setSpectrumPlacement(selected,'spectrum',((e.clientX-r.left)/r.width)*100);});}const discard=q('#spectrum-discard');if(discard){discard.addEventListener('dragover',e=>e.preventDefault());discard.addEventListener('drop',e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');setSpectrumPlacement(id,'irrelevant',0);});discard.addEventListener('click',e=>{if(selected&&!e.target.closest('.spectrum-card,.spectrum-remove'))setSpectrumPlacement(selected,'irrelevant',0);});}qa('[data-clear-spectrum]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();clearSpectrumPlacement(b.dataset.clearSpectrum);}));qa('[data-mobile-place]').forEach(b=>b.addEventListener('click',()=>{if(!selected){showError('Tap one evidence card first.');return;}setSpectrumPlacement(selected,'spectrum',Number(b.dataset.mobilePlace));}));q('[data-mobile-discard]')?.addEventListener('click',()=>{if(!selected){showError('Tap one evidence card first.');return;}setSpectrumPlacement(selected,'irrelevant',0);});}
function spectrumEvidenceOptions(){const a=state.answers,placements=a.spectrumPlacements||{};return (a.encountered||[]).filter(e=>placements[e.id]?.bucket==='spectrum');}
function renderFinal(screen){const a=state.answers,relevant=spectrumEvidenceOptions();const claim=a.finalClaim||'';screen.innerHTML=`<div class="screen-card"><div class="eyebrow">FINAL FINDING</div>${previousChip(`You began ${stanceLabel(a.initialStance)}. Then you sorted your evidence across the argument.`)}<h2>Commit to a claim.</h2><p class="lede compact-lede">No “depends” this time. Choose the statement that best matches the pattern you made, then select the strongest evidence you would use to defend it.</p><div class="choice-grid final-claim-grid">${choiceCard('finalClaim','can','Pornography can be art','Some pornography can legitimately count as art.')}${choiceCard('finalClaim','cannot','Pornography should not be classified as art','For me, the category of pornography remains outside art.')}</div><div class="prompt-block"><span class="question-label">Choose your strongest evidence</span><div class="final-evidence-grid">${relevant.map(e=>checkCard('finalEvidence',e.id,e.title,`${e.medium||'case'} · ${e.decision||'your earlier decision'}`)).join('')||'<div class="callout">You placed every dossier in the irrelevant tray. Move at least one back onto the spectrum before continuing.</div>'}</div></div><div class="prompt-block"><label class="field"><span>How sure are you? <strong id="final-confidence-value">${a.finalConfidence||70}</strong>%</span><input id="final-confidence" type="range" min="40" max="100" step="10" value="${a.finalConfidence||70}"></label></div>${promptText('finalReason','State your answer and defend it','Start: I believe... because... My strongest evidence is...')} ${promptText('metacognition','One thing that changed','Start: At first I thought... After the cases...')} ${errorBox()}</div>`;q('#final-confidence').addEventListener('input',e=>q('#final-confidence-value').textContent=e.target.value);if(claim){const el=q(`[name="finalClaim"][value="${claim}"]`);if(el)el.checked=true;}(a.finalEvidence||[]).forEach(id=>{const el=q(`[name="finalEvidence"][value="${CSS.escape(id)}"]`);if(el)el.checked=true;});}
function renderComplete(screen){const a=state.answers;const shift=Number(a.finalStance)-Number(a.initialStance);screen.innerHTML=`<div class="screen-card"><div class="eyebrow">ROUTE COMPLETE</div><h2>Your answer has a <span class="serif">history.</span></h2><p class="lede">The important part is not whether you changed sides. It is whether you can now see the rule behind your answer and where that rule gets difficult.</p><div class="delta-board"><div><span class="question-label">You began</span><div class="big-score">${esc(stanceLabel(a.initialStance))}</div><span>${esc(a.initialConfidence)}% sure</span></div><div class="arrow">→</div><div><span class="question-label">You ended</span><div class="big-score">${esc(stanceLabel(a.finalStance))}</div><span>${esc(a.finalConfidence)}% sure</span></div></div><div class="callout"><strong>Your route was yours:</strong> the examples you saw were chosen from the reasons and decisions you made along the way.</div><div style="display:flex;gap:12px;flex-wrap:wrap"><button class="button primary" id="export-now" type="button">Build PDF + QR</button><button class="button ghost" id="reset-activity" type="button">Start a new route</button></div></div>`;q('#export-now').addEventListener('click',openExport);q('#reset-activity').addEventListener('click',()=>{if(confirm('Clear this route and start again?')){S.clearState();state=S.createSession();state.answers.journeyVersion=JOURNEY_VERSION;currentKey='welcome';S.saveState(state);render();}});}

function labelVerdict(v){return ({yes:'Art',both:'Both art and pornography',no:'Not art',unsure:'Need another fact'})[v]||v;}
function validateAndCommit(){clearError();const a=state.answers;
  if(currentKey==='welcome'){const code=q('#student-code').value.trim();if(!code){showError('Add your student or group code first.');return false;}if(code.toLowerCase()==='teacher'){window.location.href='teacher.html';return false;}a.studentCode=code;a.workMode=q('#work-mode').value;}
  else if(currentKey==='instinct'){const st=checked('initialStance');if(st===null){showError('Choose the answer closest to your first reaction.');return false;}if(!validateText('instinctWhy'))return false;a.initialStance=Number(st);a.initialConfidence=Number(q('#confidence').value);a.instinctWhy=val('instinctWhy').trim();}
  else if(currentKey==='reason'){const r=checked('primaryReason');if(!r){showError('Choose the reason that matters most to you right now.');return false;}a.primaryReason=r;state.route=[`r:${r}`];}
  else if(currentKey==='challenge1'||currentKey==='challenge2'){const n=currentKey==='challenge1'?1:2;const v=checked(`challenge${n}Verdict`),f=checked(`challenge${n}Fact`);if(!v||!f){showError('Make both choices before you continue.');return false;}if(!validateText(`challenge${n}Reflection`))return false;const cc=(n===1?firstCase():secondCase());a[`challenge${n}Verdict`]=v;a[`challenge${n}VerdictLabel`]=labelVerdict(v);a[`challenge${n}Fact`]=f;a[`challenge${n}FactLabel`]=({purpose:'Purpose',work:'The work itself',context:'Context',ethics:'Ethics'})[f]||f;a[`challenge${n}FactText`]=cc.facts?.[f]||'';a[`challenge${n}Reflection`]=val(`challenge${n}Reflection`).trim();a[`challenge${n}Case`]=cc.title;a[`challenge${n}CaseId`]=cc.id;updateEncounter(`challenge${n}`,{decision:`${labelVerdict(v)}`,evidence:cc.facts?.[f]||''});if(!state.route.includes(`c${n}:${cc.id}`))state.route.push(`c${n}:${cc.id}`);}
  else if(currentKey==='checkpoint1'){const c=checked('checkpointChange'),p=checked('nextPressure');if(!c||!p){showError('Choose how much the example affected you, then choose what you want tested next.');return false;}a.checkpointChange=c;a.nextPressure=p;if(!state.route.includes(`p:${p}`))state.route.push(`p:${p}`);}
  else if(currentKey==='memory'){const k=checked('keepPart');if(!k){showError('Choose the part of your thinking you want to keep.');return false;}if(!validateText('sourceReflection'))return false;a.keepPart=k;a.sourceReflection=val('sourceReflection').trim();}
  else if(currentKey==='rule'){const parts=selected('ruleParts');if(parts.length<2||parts.length>3){showError('Choose two or three parts for your rule.');return false;}if(!validateText('framework'))return false;a.ruleParts=parts;a.framework=val('framework').trim();}
  else if(currentKey==='transfer'){const v=checked('transferVerdict'),l=checked('transferLesson');if(!v||!l){showError('Apply your rule, then decide what the result tells you.');return false;}const tc=transferCase();a.transferVerdict=v;a.transferLesson=l;a.transferCase=tc.title;a.transferCaseId=tc.id;updateEncounter('transfer',{decision:`Transfer decision: ${labelVerdict(v)}`,evidence:`Rule test: ${l}`});if(!state.route.includes(`t:${tc.id}`))state.route.push(`t:${tc.id}`);}
  else if(currentKey==='customcase'){if(!commitCustomCase())return false;}
  else if(currentKey==='spectrum'){const items=a.encountered||[],placements=a.spectrumPlacements||{};if(items.some(e=>!placements[e.id])){showError('Place every dossier on the spectrum or in the irrelevant tray.');return false;}if(!items.some(e=>placements[e.id]?.bucket==='spectrum')){showError('Keep at least one dossier on the spectrum so you have evidence for your final claim.');return false;}a.spectrumCompletedAt=S.now();if(!state.route.includes('spectrum'))state.route.push('spectrum');}
  else if(currentKey==='final'){const claim=checked('finalClaim'),evidence=selected('finalEvidence');if(!claim){showError('Choose one final claim.');return false;}if(!evidence.length){showError('Choose at least one dossier as evidence for your claim.');return false;}if(evidence.length>3){showError('Choose no more than three strongest pieces of evidence.');return false;}if(!validateText('finalReason'))return false;if(!validateText('metacognition'))return false;a.finalClaim=claim;a.finalEvidence=evidence;a.finalStance=claim==='can'?3:-3;a.finalConfidence=Number(q('#final-confidence').value);a.finalReason=val('finalReason').trim();a.metacognition=val('metacognition').trim();state.completedAt=S.now();}
  commitTiming();S.saveState(state);return true;
}
function goNext(){if(!validateAndCommit())return;commitNode(selectNextNode(currentKey));}

let clipboardToastTimer=null;function clipboardNotice(kind){let el=q('#clipboard-toast');if(!el){el=document.createElement('div');el.id='clipboard-toast';el.className='clipboard-toast';document.body.appendChild(el);}el.textContent='Write your answer here in your own words.';el.classList.add('show');clearTimeout(clipboardToastTimer);clipboardToastTimer=setTimeout(()=>el.classList.remove('show'),1800);}
function recordClipboard(k){ensureTelemetry();state.telemetry.clipboard[k]=(state.telemetry.clipboard[k]||0)+1;if(k==='paste')state.telemetry.pasteEvents=(state.telemetry.pasteEvents||0)+1;S.saveState(state);clipboardNotice(k);}
function recordTyping(el,e){ensureTelemetry();const t=state.telemetry,ty=t.typing,name=el.name||el.id||'field',now=S.now(),type=String(e.inputType||'');t.inputEvents=(t.inputEvents||0)+1;ty.events=(ty.events||0)+1;const f=t.fieldTyping[name]||(t.fieldTyping[name]={events:0,insertedChars:0,deletes:0,pauses:0,activeTypingMs:0,lastAt:0});f.events++;if(type.startsWith('delete')){t.deleteEvents=(t.deleteEvents||0)+1;ty.deleteEvents=(ty.deleteEvents||0)+1;f.deletes++;}else if(type.startsWith('insert')){const n=Math.max(1,String(e.data??'').length);ty.insertedChars=(ty.insertedChars||0)+n;f.insertedChars=(f.insertedChars||0)+n;}const last=ty.lastAt||0,gap=last?now-last:0;if(!last||gap>2500){if(last){ty.pauses=(ty.pauses||0)+1;f.pauses=(f.pauses||0)+1;}ty.bursts=(ty.bursts||0)+1;ty.currentBurstEvents=1;}else{ty.currentBurstEvents=(ty.currentBurstEvents||0)+1;ty.activeTypingMs=(ty.activeTypingMs||0)+Math.min(gap,2000);f.activeTypingMs=(f.activeTypingMs||0)+Math.min(gap,2000);}ty.maxBurstEvents=Math.max(ty.maxBurstEvents||0,ty.currentBurstEvents||0);ty.lastAt=now;f.lastAt=now;}
function attachInstrumentation(){ensureTelemetry();qa('textarea,input[type="text"],input:not([type])').forEach(el=>{el.setAttribute('autocomplete','off');if(el.tagName==='TEXTAREA')el.setAttribute('spellcheck','true');el.addEventListener('beforeinput',e=>{const type=String(e.inputType||'');if(type==='insertFromPaste'||type==='insertFromDrop'||type==='insertFromYank'){e.preventDefault();recordClipboard(type==='insertFromDrop'?'drop':'paste');return;}recordTyping(el,e);});['paste','copy','cut','drop'].forEach(kind=>el.addEventListener(kind,e=>{e.preventDefault();recordClipboard(kind);}));el.addEventListener('dragover',e=>e.preventDefault());el.addEventListener('keydown',e=>{const mod=e.ctrlKey||e.metaKey,key=String(e.key||'').toLowerCase();if((mod&&['c','v','x'].includes(key))||(e.shiftKey&&key==='insert')||(e.ctrlKey&&key==='insert')||(e.shiftKey&&key==='delete')){e.preventDefault();recordClipboard(key==='c'?'copy':key==='x'?'cut':'paste');}});el.addEventListener('focus',()=>{const n=el.name||el.id||'field';state.telemetry.fieldVisits[n]=(state.telemetry.fieldVisits[n]||0)+1;});});}

function makeQRValue(payload){if(location.protocol==='http:'||location.protocol==='https:'){const u=new URL('teacher.html',location.href);u.hash='q='+encodeURIComponent(payload);return u.href;}return payload;}
function answerBlock(title,text){return `<div class="print-section"><h2>${esc(title)}</h2><div class="print-answer"><p>${esc(text||'').replace(/\n/g,'<br>')}</p></div></div>`;}
function printEvidenceCards(){const items=(state.answers.encountered||[]);if(!items.length)return '';return `<div class="print-section"><h2>Evidence collected on this route</h2><div class="print-evidence-grid">${items.map((e,i)=>`<div class="print-evidence-card">${(e.remoteImage||e.image)?`<img src="${esc(e.remoteImage||e.image)}" data-fallback="${esc(e.remoteImage&&e.image?e.image:'')}" alt="${esc(e.imageAlt||e.title)}" referrerpolicy="no-referrer" onerror="if(this.dataset.fallback&&this.src!==this.dataset.fallback){this.src=this.dataset.fallback}">`:`<div class="print-evidence-fallback">${esc((e.medium||'CASE').slice(0,12))}</div>`}<span>FILE ${String(i+1).padStart(2,'0')} · ${esc(e.medium||'case')}</span><strong>${esc(e.title)}</strong>${e.decision?`<small>${esc(e.decision)}</small>`:''}</div>`).join('')}</div></div>`;}
function finalClaimLabel(){return state.answers.finalClaim==='cannot'?'Pornography should not be classified as art':'Pornography can be art';}
function printCustomCase(){const c=state.answers.customCase;if(!c)return '';return `<div class="print-section"><h2>Student-added dossier</h2><p><strong>${esc(c.title)}</strong> · ${esc(c.medium)}${c.creator?` · ${esc(c.creator)}`:''}<br>Initial classification: ${esc(labelVerdict(c.verdict))}${c.url?`<br>Source: ${esc(c.url)}`:''}</p><div class="print-answer"><p>${esc(c.reflection)}</p></div></div>`;}
function printSpectrum(){const a=state.answers,items=a.encountered||[],placements=a.spectrumPlacements||{};const line=items.filter(e=>placements[e.id]?.bucket==='spectrum'),irrelevant=items.filter(e=>placements[e.id]?.bucket==='irrelevant');if(!items.length)return '';return `<div class="print-section"><h2>How I sorted the evidence</h2><div class="print-spectrum"><div class="print-spectrum-label left">Pornography<br><strong>can be art</strong></div><div class="print-spectrum-label mid">grey area</div><div class="print-spectrum-label right">Pornography<br><strong>is not art</strong></div><div class="print-spectrum-axis"></div>${line.map((e,i)=>`<div class="print-spectrum-marker" style="--x:${placements[e.id].position}%;--row:${i%3}">${esc(e.title)}</div>`).join('')}</div>${irrelevant.length?`<div class="print-irrelevant"><strong>Irrelevant / did not help my argument</strong>${irrelevant.map(e=>`<span>${esc(e.title)}</span>`).join('')}</div>`:''}</div>`;}
function buildPrintReport(){const a=state.answers,payload=S.encodeTelemetry(state),qrValue=makeQRValue(payload),qr=window.TOKQR.renderDataURL(qrValue,{scale:5,margin:4,level:'M'});const root=q('#print-root');const ruleLabels=(a.ruleParts||[]).map(x=>criteria[x]?.label||x).join(', ');const finalEvidence=(a.finalEvidence||[]).map(id=>(a.encountered||[]).find(e=>e.id===id)?.title||id).join('; ');root.innerHTML=`<section class="print-page"><h1 class="print-title">BOUNDARY / ART</h1><div class="print-sub">TOK reasoning trail · ${esc(a.studentCode)} · ${esc(a.workMode)} · ${esc(state.sessionId)}</div>${printEvidenceCards()}<div class="print-section"><h2>Starting point</h2><p><strong>${esc(stanceLabel(a.initialStance))}</strong> · ${esc(a.initialConfidence)}% sure</p></div>${answerBlock('First reason',a.instinctWhy)}<div class="print-section"><h2>First factor chosen</h2><p><strong>${esc(criteria[a.primaryReason]?.label||a.primaryReason)}</strong> - ${esc(criteria[a.primaryReason]?.plain||'')}</p></div><div class="print-section"><h2>Challenge 1</h2><p><strong>${esc(a.challenge1Case)}</strong><br>Decision: ${esc(labelVerdict(a.challenge1Verdict))}<br>Evidence that mattered most: ${esc(a.challenge1FactText||a.challenge1FactLabel||a.challenge1Fact)}</p></div>${answerBlock('Reasoning after challenge 1',a.challenge1Reflection)}</section><section class="print-page"><h1 class="print-title">PRESSURE / REVISION</h1><div class="print-section"><h2>Challenge 2</h2><p><strong>${esc(a.challenge2Case)}</strong><br>Decision: ${esc(labelVerdict(a.challenge2Verdict))}<br>Evidence that mattered most: ${esc(a.challenge2FactText||a.challenge2FactLabel||a.challenge2Fact)}</p></div>${answerBlock('Reasoning after challenge 2',a.challenge2Reflection)}${answerBlock('What I changed or added to my first answer',a.sourceReflection)}<div class="print-section"><h2>My rule</h2><p><strong>Parts:</strong> ${esc(ruleLabels)}</p><div class="print-answer"><p>${esc(a.framework)}</p></div></div><div class="print-section"><h2>Transfer test</h2><p><strong>${esc(a.transferCase||'Transfer case')}</strong><br>Decision: ${esc(a.transferVerdict)}<br>What it taught me: ${esc(a.transferLesson)}</p></div>${printCustomCase()}</section><section class="print-page"><h1 class="print-title">THE EVIDENCE MAP</h1>${printSpectrum()}<div class="print-claim"><strong>${esc(finalClaimLabel())}</strong><span>Evidence selected: ${esc(finalEvidence||'--')}</span></div>${answerBlock('My final answer',a.finalReason)}${answerBlock('What changed in my thinking',a.metacognition)}<div class="print-section"><h2>Position movement</h2><p><strong>Start:</strong> ${esc(stanceLabel(a.initialStance))} (${esc(a.initialConfidence)}%)<br><strong>Final claim:</strong> ${esc(finalClaimLabel())} (${esc(a.finalConfidence)}% sure)</p></div></section><section class="print-page"><h1 class="print-title">TEACHER HANDOFF</h1><div class="print-section"><h2>Scan the activity record</h2><img class="print-qr" src="${qr}" alt="Teacher report QR"><p class="print-foot">The QR contains a compact activity record for teacher review, including route and evidence-placement data. Full written answers remain in this PDF.</p></div></section>`;return {payload,qrValue};}
function openExport(){const out=buildPrintReport(),box=q('#export-qr');box.innerHTML='';const canvas=document.createElement('canvas');window.TOKQR.renderToCanvas(out.qrValue,canvas,{scale:5,margin:4,level:'M'});box.appendChild(canvas);q('#export-dialog').showModal();}
function startPrint(){buildPrintReport();setTimeout(()=>window.print(),100)}
function initClock(){if(activeTimer)clearInterval(activeTimer);activeTimer=setInterval(()=>{if(document.visibilityState==='visible'&&document.hasFocus())state.telemetry.activeMs=(state.telemetry.activeMs||0)+1000;if((state.telemetry.activeMs||0)%10000===0)S.saveState(state);},1000);window.addEventListener('blur',()=>{state.telemetry.focusLosses=(state.telemetry.focusLosses||0)+1;S.saveState(state)});window.addEventListener('beforeunload',()=>S.saveState(state));}
q('#next-btn').addEventListener('click',goNext);q('#print-btn').addEventListener('click',startPrint);initClock();render();
})();
